return {season_1={adventure_id=101,adventure_name="暗夜拾光",battle_pass_id="battle_pass_23001",chapter_count=6,collection_tasks={{available_from="2026-09-30 04:00:00",conditions={"集齐S1赛季的赛季新精灵进化链"},name="S1图鉴：收集该赛季的所有新精灵进化链",reward_id="reward_201108"}},encounter_text="于暗夜拾光赛季相遇",id="season_1",name="暗夜拾光",new_pets={{avatar="PetAvatar_3180.png",description="探索欲很强的精灵，会通过摇尾巴的方式表达亲近，尾尖会散发出魔法，但并不能很好的控制，时常伤到自己。",id="pet_000159",name="小帕尔",page_title="小帕尔",pictorial_book_id=293,portrait="PetPortrait_xiaopaersasi.png",source_id=3180,type_ids={18}},{avatar="PetAvatar_3181.png",description="头顶的独角锋利又坚硬，但不蕴含魔法，脱落下来的独角最早被洛克用来制作匕首。“他眼中看到的都是黑白的，他的世界没有色彩，单一的世界却让他有了执著的信念和忠诚的心。”",id="pet_000160",name="帕尔萨斯",page_title="帕尔萨斯",pictorial_book_id=294,portrait="PetPortrait_paersasi2.png",source_id=3181,type_ids={18}},{avatar="PetAvatar_3182.png",description="在古老的典籍中记载，龙息帕尔和其他恶系精灵的行事风格不同，它们秉持等价交换的原则，会严格遵守自己缔结的契约。在契约完成前绝不会离开，甚至愿意为此等待漫长的时光。",id="pet_000161",name="龙息帕尔",page_title="龙息帕尔",pictorial_book_id=295,portrait="PetPortrait_longxipaer.png",source_id=3182,type_ids={18}},{avatar="PetAvatar_3244.png",description="绒绒多在夜间活动，触角能感知星光，体表覆盖着细密的短绒，能吸附少量蕴含星光的细微粉末。偶尔主动靠近洛克，以柔软的身体轻蹭对方，习性黏人，是温顺的小型毛绒精灵。",id="pet_000207",name="绒绒",page_title="绒绒",pictorial_book_id=307,portrait="PetPortrait_rongrong.png",source_id=3244,type_ids={6,13}},{avatar="PetAvatar_3245.png",description="体表的短绒进化为蓬松且带有黏性的长绒，能够吸附并储存更多星光粉末，直接触摸的话，会感到轻微刺痛。它们吸附的粉末最终在体内融合，驱动体内组织发生解离和重塑，当能量饱和时，绒毛能爆发出强劲的冲击力。",id="pet_000208",name="小绒茧",page_title="小绒茧",pictorial_book_id=308,portrait="PetPortrait_xiaorongjian.png",source_id=3245,type_ids={6,13}},{avatar="PetAvatar_3246.png",description="完全发育成型，翅脉中流动着体液，横脉与纵脉交汇处形成规整的星形花纹，蕴含强烈的星光能量。胸节与携粉足极度膨大，布满致密的长绒，能牢牢黏附超多光系魔法粉末——这些粉末正是体液代谢后的产物。",id="pet_000209",name="绒仙子",page_title="绒仙子",pictorial_book_id=309,portrait="PetPortrait_rongxianzi.png",source_id=3246,type_ids={6,13}},{avatar="PetAvatar_3309.png",description="足部又软又嫩，相当虚弱无力。双眼的视觉暂未发育完全，偶尔被毛发遮挡视野。研究推测其毛发承担了主要感官的功能，在看不清的时候也可以通过毛发的感光功能，早早隐藏好自己。",id="pet_000258",name="犀角鸟",page_title="犀角鸟",pictorial_book_id=310,portrait="PetPortrait_xijiaoniao.png",source_id=3309,type_ids={6}},{avatar="PetAvatar_3310.png",description="毛发柔软但有韧性，结构特殊，似乎每一根毛发都能接收和发射光能量。它们可以分辨来自四面八方所有光束的到达时间，比较每个光束抵达的时间，计算其距离和能量。",id="pet_000259",name="光纤兽",page_title="光纤兽",pictorial_book_id=311,portrait="PetPortrait_guangjiaoshou.png",source_id=3310,type_ids={6}},{avatar="PetAvatar_3311.png",description="在月亮升起来之后活动，某些特定时间会散发出微弱光芒，与某些弱小的夜行生物存在共生关系。光能量在每根毛发中沿“之”字形向身体内部传输，可以完好无损地传输到体内，存储凝结成强大力量。",id="pet_000260",name="疾光千兽",page_title="疾光千兽",pictorial_book_id=312,portrait="PetPortrait_jiguangqianshou.png",source_id=3311,type_ids={6}},{avatar="PetAvatar_3319.png",description="习性和语言都与目前所知的任何精灵种族不同，身体轻盈，皮肤柔软但极其有韧性。研究学者偶然拾取到它星星飘下的碎屑，密度极高但质量非常轻，研究发现其材质也不属于卡洛西亚大陆的任何一种已知材质。",id="pet_000264",name="粉星仔",page_title="粉星仔",pictorial_book_id=335,portrait="PetPortrait_fenxingzai.png",source_id=3319,type_ids={20}},{avatar="PetAvatar_3320.png",description="踏着流星而来的信使，在洛克族里传闻对着它们说话有概率可以梦想成真。它们总是很着急，在夜幕下如同一道道银针般穿行，谁让这世间的许愿总是太多、太多了呢。",id="pet_000265",name="粉耳星兔",page_title="粉耳星兔",pictorial_book_id=336,portrait="PetPortrait_fenerxingtu.png",source_id=3320,type_ids={20}},{avatar="PetAvatar_3485.png",description="“能够在流星上倾听许愿的家伙，总会被认为是善良的吧？嘻嘻，它们可从来没说过会以什么方式实现哦！扭曲的实现也是实现。不愿以他人的理想为自己一生的追求，却也无法逃脱命运的桎梏。那么来吧，向它们许愿吧”！",id="pet_000385",name="落陨星兔",page_title="落陨星兔",pictorial_book_id=337,portrait="PetPortrait_luoyunxingtu.png",source_id=3485,type_ids={20,17}},{avatar="PetAvatar_3436.png",description="“请避免在秋季携带柴渣虫进入山林，若因未采取防火措施而促成险情，洛克将承担所有责任。”——一则来自魔法部的公告",id="pet_000340",name="柴渣虫",page_title="柴渣虫",pictorial_book_id=325,portrait="PetPortrait_chaizhachong.png",source_id=3436,type_ids={4,3}},{avatar="PetAvatar_3437.png",description="木头已经失去了生命迹象，没有实体的火焰精灵在死去木头的身体里栖息。往往喜欢热闹，洛克族的亲近和合作关系会让它们非常自豪。",id="pet_000341",name="燃薪虫",page_title="燃薪虫",pictorial_book_id=326,portrait="PetPortrait_ranxinchong.png",source_id=3437,type_ids={4,3}},{avatar="PetAvatar_3614.png",description="“经实验发现，其腹部含有特殊的器官，只对光系能量产生反应。因此，存放光水晶时需派遣光系精灵巡逻，混淆它们的感应。”“光系精灵一同发出抗议，要求王国打击嗜光嗡嗡的狂热跟踪和过分亲近行为。”",id="pet_000479",name="嗜光嗡嗡",page_title="嗜光嗡嗡",pictorial_book_id=323,portrait="PetPortrait_shiguangwengweng.png",source_id=3614,type_ids={18,6}},{avatar="PetAvatar_3615.png",description="在微光沼泽，有不少因为长期触光水晶而琥珀化的精灵，这里面却没有恶名昭著的窃光蚊。这是因为窃光蚊会互相合作，一旦有个体吸收了过多光系能量，其他伙伴就会去吸收，帮助其减少体内的能量浓度。",id="pet_000480",name="窃光蚊",page_title="窃光蚊",pictorial_book_id=324,portrait="PetPortrait_qieguangwen.png",source_id=3615,type_ids={18,6}},{avatar="PetAvatar_3382.png",description="头顶的光似乎并不是光系魔法，而是来自于某种寄生在其身上的会发光的细菌，目前不清楚发光细菌的其他特性，即使在水中也必须把头顶的灯伸到水面上。",id="pet_000309",name="双灯鱼",page_title="双灯鱼",pictorial_book_id=320,portrait="PetPortrait_shungdengyu.png",source_id=3382,type_ids={5,11}},{avatar="PetAvatar_3383.png",description="独居生物，个体之间保持距离，互不侵犯。常常自言自语，狂笑乱跳。据研究它们头顶的灯内有百万只以上的发光菌，肉眼很难观察。每只菌似乎都有独立意识，能够和本体进行沟通，甚至还有可能侵蚀本体的脑。",id="pet_000310",name="利灯鱼",page_title="利灯鱼",pictorial_book_id=321,portrait="PetPortrait_lidengyu.png",source_id=3383,type_ids={5,11}},{avatar="PetAvatar_3198.png",description="身体里流淌着神秘的星光能量，打喷嚏的时候会下星星雨。喜欢聚在一起舞蹈，舞蹈时能看到漂亮的星光在它们周围环绕，推测这是粉粉星们交流的一种方式。",id="pet_000175",name="粉粉星",page_title="粉粉星",pictorial_book_id=330,portrait="PetPortrait_fenfenxing.png",source_id=3198,type_ids={11,20}},{avatar="PetAvatar_3199.png",description="浑身散发着紫色的微光，有时会在夜晚拿出珍藏的星星，为迷途的旅人照亮归途。得益于柔软的身体结构，能够将不稳定的星光能量储存在体内，据说星星的亮度代表着存储能量的强度。",id="pet_000176",name="小皮球",page_title="小皮球",pictorial_book_id=331,portrait="PetPortrait_xiaopiqiu.png",source_id=3199,type_ids={11,20}},{avatar="PetAvatar_3457.png",description="额前的星星质地不明，触感温热，能够从其中检测到异常的魔力波动。如果星星离开身体太远的话，身体会进入沉睡状态。“虽然它从不去看，但是魔法丢得很准。”",id="pet_000358",name="月牙雪熊",page_title="月牙雪熊",pictorial_book_id=322,portrait="PetPortrait_yueyaxuexiong.png",source_id=3457,type_ids={9,20}},{avatar="PetAvatar_3203.png",description="拥有坚硬而沉重的外壳，靠石头和木头补充能量，在能量短缺的时候会靠睡觉度过。\n“它是坚硬的，它永远不会破碎。可当你狠心地对待它，它终究会伤心地沉睡。”",id="pet_000180",name="贝瑟",page_title="贝瑟",pictorial_book_id=332,portrait="PetPortrait_beise.png",source_id=3203,type_ids={19,4}},{avatar="PetAvatar_3204.png",description="身体结构十分精巧，能够最高效地利用能源，是某些发热供暖装置的设计原型。但在氧气不足的地方身体会逐渐冷下来进入睡眠状态。“经过了岁月的磨练和沉淀，透露出时光的浑厚。”",id="pet_000181",name="贝加尔",page_title="贝加尔",pictorial_book_id=333,portrait="PetPortrait_beijiaer.png",source_id=3204,type_ids={19,4}},{avatar="PetAvatar_3205.png",description="能够通过头顶的蒸汽猜出贝古斯的心情，对于它们而言，不同的心情需要消耗不同数量的矿石。\n“它是安静的，像座山一样，守候在这里，亘古不变，然而它又是有生命的，内心之中迸发出无限的生机。”",id="pet_000182",name="贝古斯",page_title="贝古斯",pictorial_book_id=334,portrait="PetPortrait_beigusi.png",source_id=3205,type_ids={19,4}},{avatar="PetAvatar_3148.png",description="夜晚很容易在破旧的空屋见到。力量弱小但长着骇人的面容，会恐吓其他精灵，以此来保护自己。它几乎不依赖视觉，通过感知热量来判断生物的位置与距离。",id="pet_000134",name="空空颅",page_title="空空颅",pictorial_book_id=327,portrait="PetPortrait_anyekulou.png",source_id=3148,type_ids={17}},{avatar="PetAvatar_3149.png",description="吓退其他精灵以取乐，有人说它们以恐惧为食，但没人考证过真假。长出双爪后，行动更加自如，有了保护自己的能力。",id="pet_000135",name="夜宿颅",page_title="夜宿颅",pictorial_book_id=328,portrait="PetPortrait_yejumo.png",source_id=3149,type_ids={17}},{avatar="PetAvatar_3150.png",description="充盈着魔力的巨爪十分有力，曾经被夜枭吞下过的生命，虽然躯体看似无碍，灵魂却缺失了一部分。",id="pet_000136",name="夜枭",page_title="夜枭",pictorial_book_id=329,portrait="PetPortrait_yexiao.png",source_id=3150,type_ids={17}}},page_title="暗夜拾光",season_label="S1赛季",source_id=1,task_count=38,visual={backdrop="Season_1_HandbookBg.png",battle_pass_background="BattlePass_23001_Background.png",hero="Season_1_Hero.png",title="Season_1_Title.png"},window={["end"]="2026-05-21 03:59:59",start="2026-03-26 04:00:00",timezone="UTC+8"}},season_2={adventure_id=102,adventure_name="狂欢怪谈",battle_pass_id="battle_pass_23002",chapter_count=5,collection_tasks={{available_from="2026-09-30 04:00:00",conditions={"集齐S2赛季的赛季新精灵进化链"},name="S2图鉴：收集该赛季的所有新精灵进化链",reward_id="reward_201108"}},encounter_text="于狂欢怪谈赛季相遇",id="season_2",name="狂欢怪谈",new_pets={{avatar="PetAvatar_3733.png",description="被洛克制造并赋予美好的使命，它们的底层结构里面写着“去吧，去给孩子们带来快乐吧。”于是它们年复一年日复一日，用不太灵光的脑袋想，用有点笨的小手做，尝试制作出所有能让洛克感觉到快乐的事物。",id="pet_000508",name="钨丝贝贝",page_title="钨丝贝贝",pictorial_book_id=348,portrait="PetPortrait_wusibeibei.png",source_id=3733,type_ids={19}},{avatar="PetAvatar_3734.png",description="经常对着空气练习，有洛克靠近时会立刻启动表演程序。有时显得笨拙不够善解人意，如果小洛克曾因为它的笑话而微笑，它可以不眠不休追着小洛克讲三天三夜的笑话，然后直接昏倒。",id="pet_000509",name="辉光幕机",page_title="辉光幕机",pictorial_book_id=349,portrait="PetPortrait_huiguangmuji.png",source_id=3734,type_ids={19}},{avatar="PetAvatar_3735.png",description="努力观察着所有洛克，曾经因为什么而变得快乐。它默默地把这些瞬间记录下来，尝试动手改造自己，用机械系的魔法制作成「心脏」，希望能够模拟感受到洛克从心底感受到的快乐。",id="pet_000510",name="机幕方舟",page_title="机幕方舟",pictorial_book_id=350,portrait="PetPortrait_jimufangzhou.png",source_id=3735,type_ids={19}},{avatar="PetAvatar_3572.png",description="肚子里有一个小小的爆焰囊，当蓄满火焰时，肚子会鼓成圆滚滚的球状。如果看到它突然捂住肚子，最好赶紧躲开——那是爆焰囊过载的警告！",id="pet_000447",name="爆焰仔",page_title="爆焰仔",pictorial_book_id=356,portrait="PetPortrait_baoyanzai.png",source_id=3572,type_ids={4,10}},{avatar="PetAvatar_3573.png",description="腹部的爆焰囊扩张了三倍，蓄能时会使整个躯体膨胀如热气球，火焰甚至会从鳞片间隙逸散。古代文献记载，曾有爆焰喷喷在火山口蓄能三天三夜，最终喷射的龙焰照亮了整个夜空。",id="pet_000448",name="爆焰喷喷",page_title="爆焰喷喷",pictorial_book_id=357,portrait="PetPortrait_baoyanpengpeng.png",source_id=3573,type_ids={4,10}},{avatar="PetAvatar_3531.png",description="头顶的眼是精致的拟态结构，而真正的眼部和头部在腹部，都还很脆弱。魔法师们发现，它的腹部有厚厚的抗冻组织，能在极寒环境中保护核心器官。",id="pet_000418",name="小雪人",page_title="小雪人",pictorial_book_id=354,portrait="PetPortrait_xiaoxueren.png",source_id=3531,type_ids={9}},{avatar="PetAvatar_3532.png",description="吃掉足够多的暴风雪后就会进化成这个样子。手里永远攥着两个雪球，试图让自己看起来凶猛一些，但其实是个温柔的大家伙，经常偷偷帮迷路的精灵们搭建避风的小雪屋。",id="pet_000419",name="雪怪",page_title="雪怪",pictorial_book_id=355,portrait="PetPortrait_xueguai.png",source_id=3532,type_ids={9}},{avatar="PetAvatar_3729.png",description="经常抓着尾巴不停讲话，通过奇妙的头部和尾部结构将自己的声音放大，这是在向周围散播“和我一起玩吧”的信号。如果观察到猴麦仔这样做，可以去和它玩耍试试，它会很开心自己的声音被洛克所听到。",id="pet_000506",name="猴麦仔",page_title="猴麦仔",pictorial_book_id=358,portrait="PetPortrait_houmaizai.png",source_id=3729,type_ids={2,19}},{avatar="PetAvatar_3730.png",description="进化后嗓门大得惊人，更加渴望被听到，想让所有洛克都听见自己的声音。同类碰面时会争抢谁先拿麦，双方轮流对着吼，谁的声音更大谁就赢。有研究员曾记录到两只音碟吼对峙了整整一周，最终以一方嗓子沙哑告终。",id="pet_000507",name="音碟吼",page_title="音碟吼",pictorial_book_id=359,portrait="PetPortrait_yindiehou.png",source_id=3730,type_ids={2,19}},{avatar="PetAvatar_3708.png",description="鼻子和尾巴末端有个圆圆的结，走路时摇摇摆摆，肚子被敲出奇妙的鼓点，其他精灵们听到后不由自主地被吸引，跟着它的鼓点巡游。",id="pet_000500",name="小鼓象",page_title="小鼓象",pictorial_book_id=371,portrait="PetPortrait_xiaoguxiang.png",source_id=3708,type_ids={19}},{avatar="PetAvatar_3709.png",description="经常把听到过的旋律一段一段地敲出来，但是它的记忆力不太好，经常把好几首曲子混在一起敲，发出谁也听不懂的节奏，只有巨鼓象自己敲得很起劲。有评论家说，虽然听不懂，但别有一番风味。",id="pet_000501",name="巨鼓象",page_title="巨鼓象",pictorial_book_id=372,portrait="PetPortrait_juguxiang.png",source_id=3709,type_ids={19}},{avatar="PetAvatar_3677.png",description="爱扎堆聊天的小话痨，走到哪聊到哪，头顶的烟花就是它们的聊天气泡，聊得越开心，烟花崩得越热闹。脑袋上噼里啪啦闪个不停，如果看到落单的烟花团一整天头上都没有冒出烟花，请多关心它的心理健康。",id="pet_000490",name="烟花团",page_title="烟花团",pictorial_book_id=365,portrait="PetPortrait_yanhuatuan.png",source_id=3677,type_ids={4,12}},{avatar="PetAvatar_3678.png",description="进化后社交圈更广了，走在城镇街道上，即使遇到不认识的精灵也能停下来聊两句。它们主动承担了一些王国业务，负责节日庆典的烟花表演，几只烟花伯爵就能组成一个专业团队。",id="pet_000491",name="烟花伯爵",page_title="烟花伯爵",pictorial_book_id=366,portrait="PetPortrait_yanhuabojue.png",source_id=3678,type_ids={4,12}},{avatar="PetAvatar_3487.png",description="在人群中偶尔觉得焦虑的小朋友，看起来有些多动，总是晃悠身体，实际上是在缓解焦虑给自己勇气，不太善于表达。",id="pet_000387",name="小丑豆豆",page_title="小丑豆豆",pictorial_book_id=362,portrait="PetPortrait_xiaochoudoudou.png",source_id=3487,type_ids={18}},{avatar="PetAvatar_3488.png",description="仍然有些闲不住，但它正在学着克制，想蹦的时候就抛球，把冲动转化到了抛球中。不过偶尔还是会忍不住，球抛着抛着身体就跟着飞了出去。",id="pet_000388",name="小丑兔",page_title="小丑兔",pictorial_book_id=363,portrait="PetPortrait_xiaochoutu.png",source_id=3488,type_ids={18}},{avatar="PetAvatar_3489.png",description="依然爱动，所有躁动化作指尖球技，它的迈步从容而有节奏，抛球的轨迹优雅得像一门艺术。它的耳朵随着每一次弹跳有规律地颤动，就像洛克喜欢抖腿，这是它唯一泄露出来的小破绽。",id="pet_000389",name="小丑公爵",page_title="小丑公爵",pictorial_book_id=364,portrait="PetPortrait_xiaochougongjue.png",source_id=3489,type_ids={18}},{avatar="PetAvatar_3683.png",description="看到洛克就想展示刚学的魔法。可惜魔力还不够，变得不太好，偶尔还有可能失败，表演失败之后它会钻进帽子里面反思，过一会儿又探出脑袋继续尝试。",id="pet_000492",name="咕咕帽",page_title="咕咕帽",pictorial_book_id=367,portrait="PetPortrait_gugumao.png",source_id=3683,type_ids={17}},{avatar="PetAvatar_3684.png",description="认为变出东西的魔法很厉害，于是想要传授给其他精灵这项技术，可惜其他精灵都不是很感兴趣，只有咕咕帽不厌其烦地每天请教，它很开心，于是更加殷切地陪练。",id="pet_000493",name="咕德帽帽",page_title="咕德帽帽",pictorial_book_id=368,portrait="PetPortrait_gudemaomao.png",source_id=3684,type_ids={17}},{avatar="PetAvatar_3659.png",description="身体柔软，会随着水流轻轻摇摆，安静无害，常被误认为普通的装饰，似乎并不想进化。曾有洛克研究员研究这一物种后感概：生命自有出路。",id="pet_000486",name="加油海葵",page_title="加油海葵",pictorial_book_id=360,portrait="PetPortrait_jiayouhaikui.png",source_id=3659,type_ids={5,16}},{avatar="PetAvatar_3660.png",description="加油海葵放弃了锤炼自己变得更强这一进化手段，它们和加油蟹一起构建出特殊的共生关系。这个世界足够宽容，小小精灵不必努力变得更强大，只要健康快乐就好。",id="pet_000487",name="加油蟹",page_title="加油蟹",pictorial_book_id=361,portrait="PetPortrait_jiayouxie.png",source_id=3660,type_ids={5,16}},{avatar="PetAvatar_3234.png",description="总是一副亲切愉悦的样子，备受小洛克们的喜欢，但似乎在没人的时候它们不会展现出一丁点生气。曾经不分昼夜持续观测一年，且让样本知道自己被观测，期间样本呈现愉悦的状态。停止观测一小时后样本所有生命体征均消失。",id="pet_000200",name="牵线木偶",page_title="牵线木偶",pictorial_book_id=373,portrait="PetPortrait_qianxianmuou.png",source_id=3234,type_ids={20}},{avatar="PetAvatar_3235.png",description="非常偶然的情况下发现它们殴打自己身上闪烁着的微光的提线。提线中流动着强大魔力，以此来操纵结构精巧的木质结构身体，看似十分脆弱，但在幻系魔力的支撑下，有着令人意想不到的破坏力。",id="pet_000201",name="帅帅魔偶",page_title="帅帅魔偶",pictorial_book_id=374,portrait="PetPortrait_shuaishuaimoou.png",source_id=3235,type_ids={20}},{avatar="PetAvatar_3736.png",description="自己不能发光，但背部覆盖着镜面般的鳞片，蜷缩成球就可以把微小的光芒反射成绚烂的闪光。拥有很多的爱，常常兴奋地滚向最近的洛克！想在闪光中跳跃，想一起共舞一辈子！",id="pet_000511",name="炫光迪迪",page_title="炫光迪迪",pictorial_book_id=369,portrait="PetPortrait_xuanguangdidi.png",source_id=3736,type_ids={11,6}},{avatar="PetAvatar_3737.png",description="古老物种在漫长的时间里发生演化，曾经独自栖息在安静与黑暗里面，偶尔靠敲击山石的回音和其他个体沟通。这让它们对声音无比敏感和渴望，它们拥有坚定的心，一直等到可以在光里热烈地表达。",id="pet_000512",name="​​霹雳迪迪",page_title="​​霹雳迪迪",pictorial_book_id=370,portrait="PetPortrait_pilididi.png",source_id=3737,type_ids={11,6}},{avatar="PetAvatar_3743.png",description="丢失了一只海葵的加油蟹，会埋伏在同伴出没的路上，偷走对方的海葵，而被偷的那只又会去偷下一只。就这样循环往复乐在其中，总有加油蟹缺少一个海葵……",id="pet_000514",name="加油蟹",page_title="加油蟹",pictorial_book_id=361,portrait="PetPortrait_jiayouxiedanzhi.png",source_id=3743,type_ids={5,16}}},page_title="狂欢怪谈",season_label="S2赛季",source_id=2,task_count=32,visual={backdrop="Season_2_HandbookBg.png",battle_pass_background="BattlePass_23002_Background.png",hero="Season_2_Hero.png",title="Season_2_Title.png"},window={["end"]="2026-07-16 03:59:59",start="2026-05-21 04:00:00",timezone="UTC+8"}},season_3={adventure_id=103,adventure_name="铅字幻梦",battle_pass_id="battle_pass_23003",chapter_count=6,collection_tasks={{available_from="2026-09-30 04:00:00",conditions={"集齐S3赛季的赛季新精灵进化链"},name="S3图鉴：收集该赛季的所有新精灵进化链",reward_id="reward_201108"}},encounter_text="于铅字幻梦赛季相遇",id="season_3",name="铅字幻梦",new_pets={{avatar="PetAvatar_3230.png",description="圆滚滚的身体可以吃掉很多可可果也藏着很多神秘的魔法，据说它能实现人心底的愿望，但它自己却不太清楚。喜欢跟在洛克周围转悠，湿漉漉的大眼睛似乎盯着洛克书包里的可可果，又似乎是别的什么东西。",id="pet_000196",name="加灵",page_title="加灵",pictorial_book_id=414,portrait="PetPortrait_jialing.png",source_id=3230,type_ids={2,16}},{avatar="PetAvatar_3231.png",description="似乎能分辨愿望的颜色，开心的愿望是香香的粉黄色，难过的愿望是苦苦的紫黑色。它总是涂一些谁都看不懂的线条，不止在纸上涂。曾因为四处涂鸦被保洁阿姨警告过，后诚恳道歉，并在阿姨门前摆放整整十个可可果表达歉意。",id="pet_000197",name="加益",page_title="加益",pictorial_book_id=415,portrait="PetPortrait_jiayi.png",source_id=3231,type_ids={2,16}},{avatar="PetAvatar_3232.png",description="传说能够实现愿望，其实是每天只会吃东西打瞌睡的小小精灵。偶尔转转悠悠，如果没人看着可能会走去很远的地方，凭借着直觉和本能生活了很久很久。什么是直觉的来源呢？是许愿的声音吗？",id="pet_000198",name="加尔",page_title="加尔",pictorial_book_id=416,portrait="PetPortrait_jiaer.png",source_id=3232,type_ids={2,16}},{avatar="PetAvatar_3233.png",description="没有人知道它是从哪里出现的，它和加尔共用一具身体。眼珠滴溜溜地转，它聪明又凌厉，曾经严肃指出不是所有可可果它都喜欢，它明确表示不喜欢软的可可果，脆脆的口感才是最好的。",id="pet_000199",name="黑化加尔",page_title="黑化加尔",pictorial_book_id=417,portrait="PetPortrait_heihuajiaer.png",source_id=3233,type_ids={2,17}},{avatar="PetAvatar_3264.png",description="能够生产出纺线的精灵，纺线主要由卡波体内的蛋白质和唾液构成。卡波的唾液中带有某种未知诅咒，即使是同类触碰到的话也会中毒陷入昏睡。",id="pet_000220",name="卡波",page_title="卡波",pictorial_book_id=430,portrait="PetPortrait_xieefangchui.png",source_id=3264,type_ids={18}},{avatar="PetAvatar_3265.png",description="据传说卡拉波斯曾经是一个仙子，因为误会诅咒过一位公主，被诅咒反噬后变为纺锤的模样。一次最多能够拉出7000米纺线。当体内的蛋白质耗尽的时候，它们就不会再进行任何活动陷入长久的昏睡中。",id="pet_000221",name="卡拉波斯",page_title="卡拉波斯",pictorial_book_id=431,portrait="PetPortrait_hunshuifangchui.png",source_id=3265,type_ids={18}},{avatar="PetAvatar_3360.png",description="它们坚信自己是夜晚的国王，项圈是它的王冠。每天日落后就出门巡视领地，把沿途看到的硬币、纽扣、碎玻璃一切闪亮的东西都带回窝里，当作臣民的贡品。",id="pet_000291",name="蝴蝶陶陶",page_title="蝴蝶陶陶",pictorial_book_id=422,portrait="PetPortrait_hudietaotao.png",source_id=3360,type_ids={16}},{avatar="PetAvatar_3361.png",description="自封的国王现在有了配得上野心的武器：锋利的毒爪。它们夜间行动变得更加隐秘和高效，能在对方毫无察觉时把东西拿走，等对方发现时只剩爪印和一点残留的麻痹感。",id="pet_000292",name="铆钉毛毛",page_title="铆钉毛毛",pictorial_book_id=423,portrait="PetPortrait_maolaoda.png",source_id=3361,type_ids={16,12}},{avatar="PetAvatar_3362.png",description="某些地区真正的统治者，修长的身影在夜色中几乎无声，它不再需要去偷任何东西，崇拜者主动献上闪亮的礼物。爪爪大人如果遇见认可的洛克，也愿意慷慨地给点赏赐。",id="pet_000293",name="徘徊爪爪",page_title="徘徊爪爪",pictorial_book_id=424,portrait="PetPortrait_maolaoye.png",source_id=3362,type_ids={16,12}},{avatar="PetAvatar_3565.png",description="身体会散发烤栗子一样的香甜气味，同行的另一名研究员舔过之后中毒几日没有好转。有洛克曾研究过不同天气和环境里其粘液的味道变化，立志写出《栗鼠粘液美味大全》。",id="pet_000442",name="栗鼠",page_title="栗鼠",pictorial_book_id=438,portrait="PetPortrait_lishu.png",source_id=3565,type_ids={12,2}},{avatar="PetAvatar_3566.png",description="会嗅来嗅去寻找花蜜，吃的花蜜越多，鼻子分泌的粘液越香甜，并且带着花香的味道。会用鼻子把身上的毒刺都涂满香甜粘液。毛毛舔过它们却不会中毒，真奇怪。",id="pet_000443",name="壳栗丝鼠",page_title="壳栗丝鼠",pictorial_book_id=439,portrait="PetPortrait_kelisishu.png",source_id=3566,type_ids={12,2}},{avatar="PetAvatar_3591.png",description="传说它们出生在连光都沉不到的深渊底部，身上有一道还不太清晰的十字纹路，体型很小，这里的水压大到同类精灵根本待不住，但它不觉得苦，每天都在拼命往上游一点点。",id="pet_000456",name="十字蝌蚪",page_title="十字蝌蚪",pictorial_book_id=427,portrait="PetPortrait_shizikedou.png",source_id=3591,type_ids={5}},{avatar="PetAvatar_3592.png",description="从深渊底层一层一层地闯上来，会向一切挡路的精灵宣战，不管对方多大。额头的十字纹变得清晰有力，像一枚代表荣耀的徽章刻在身上。",id="pet_000457",name="十字蛙",page_title="十字蛙",pictorial_book_id=428,portrait="PetPortrait_shiziwa.png",source_id=3592,type_ids={5}},{avatar="PetAvatar_3593.png",description="它们终于站在阳光下了。身上的十字纹被光照得发亮，那是从深渊底部一直带上来的印记。不再需要向谁证明什么，也不需要任何帮助，它们骨子里的斗志永远不会消失。",id="pet_000458",name="深渊蛙",page_title="深渊蛙",pictorial_book_id=429,portrait="PetPortrait_shenyuanwa.png",source_id=3593,type_ids={5,14}},{avatar="PetAvatar_3675.png",description="据说它曾经是城堡里一位小骑士，或者至少它自己是这么认为的。不知道是谁的魔法让它变成了一截蜡烛的模样，但它好像并不太在意，依然坚守骑士的职责，在城堡巡逻，用两只小手护住火焰。",id="pet_000488",name="守夜烛",page_title="守夜烛",pictorial_book_id=432,portrait="PetPortrait_shouyezhu.png",source_id=3675,type_ids={4,6}},{avatar="PetAvatar_3676.png",description="蜡泪在身上层层叠叠凝固成了铠甲的形状，火焰也不再随时会灭，而是稳定明亮的光柱，足以照亮整条长廊。作为蜡烛精灵，它们能在最黑的夜里给出最亮的光，这让它们非常满足。",id="pet_000489",name="流明坎德拉",page_title="流明坎德拉",pictorial_book_id=433,portrait="PetPortrait_liumingkandela.png",source_id=3676,type_ids={4,6}},{avatar="PetAvatar_3697.png",description="原本只是农场里普通的稻草人，因为被洛克们日复一日地打招呼、聊天、玩猜拳，某天清晨它动了动指头，发现自己可以从木架上走下来。最喜欢猜拳，因为这是它学会的第一件事。",id="pet_000494",name="稻草人",page_title="稻草人",pictorial_book_id=436,portrait="PetPortrait_daocaoren.png",source_id=3697,type_ids={16,14}},{avatar="PetAvatar_3698.png",description="在被洛克们陪伴了足够久之后，“想要保护这里”的心情终于强大到改变了它的身体。稻草变得紧实如肌肉，布裹的拳头沉重有力，现在没有任何飞禽敢靠近它守护的农场，但对洛克们，它永远温柔。据说猜拳会故意输给洛克。",id="pet_000495",name="稻草守护者",page_title="稻草守护者",pictorial_book_id=437,portrait="PetPortrait_daocaoshouhuzhe.png",source_id=3698,type_ids={16,14}},{avatar="PetAvatar_3706.png",description="“洛克洛克，告诉我， 谁是林中最甜的果？”\n“是你，是你，比蜜更甜，比血更红， 比玛丽女王手心的那颗还要圆”。\n“那为什么没洛克来摘我？”\n“别急，别急，会有风来摘。”",id="pet_000498",name="蜜果骸",page_title="蜜果骸",pictorial_book_id=434,portrait="PetPortrait_miguohai.png",source_id=3706,type_ids={17,3}},{avatar="PetAvatar_3707.png",description="“洛克洛克，告诉我， 我还甜吗？”\n“比从前更甜，比糖更黏。”\n“那我还圆吗？”\n“比从前更圆，比月更满。”\n“洛克洛克，告诉我， 腐朽的果还有人摘吗？”",id="pet_000499",name="半朽蜜果灵",page_title="半朽蜜果灵",pictorial_book_id=435,portrait="PetPortrait_banxiumiguoling.png",source_id=3707,type_ids={17,3}},{avatar="PetAvatar_3710.png",description="古老的童话故事里面写道：如果战胜了一千只鼠精灵，就可以得到咬咬小子家族的认可。咬咬小子们似乎没听过这个故事，它们经常在路口站岗、巡逻，鼠精灵也在他们的保护范围内。",id="pet_000502",name="咬咬小子",page_title="咬咬小子",pictorial_book_id=418,portrait="PetPortrait_yaoyaoxiaozi.png",source_id=3710,type_ids={19}},{avatar="PetAvatar_3711.png",description="胡桃王子喜欢巡逻，巡逻途中偶尔会顺手把迷路的小精灵护送回家，也会挡在受惊的洛克面前。即使没有任何契约关系，胡桃王子们自发地守护着整条街道。",id="pet_000503",name="胡桃王子",page_title="胡桃王子",pictorial_book_id=419,portrait="PetPortrait_hutaowangzi.png",source_id=3711,type_ids={19}},{avatar="PetAvatar_3718.png",description="古老的童话故事里面写道：有一种被施了魔法的鸟精灵，每个夜晚都必须在月光下起舞，不然家族会遭遇不幸。足尖元件们似乎在轮班排练，动作还稍显稚嫩笨拙，随着旋转发出叮咚叮咚的曲调。",id="pet_000504",name="足尖元件",page_title="足尖元件",pictorial_book_id=420,portrait="PetPortrait_zujianyuanjian.png",source_id=3718,type_ids={20,19}},{avatar="PetAvatar_3719.png",description="在月光好的夜晚，成群的离心舞者聚在湖边旋转，远远看去像一场盛大的舞会——目击洛克说，离心舞者的舞蹈能跳出旋律，旋律像一场美梦，梦里讲述着，湖水、月光和一只银白色的鸟。",id="pet_000505",name="离心舞者",page_title="离心舞者",pictorial_book_id=421,portrait="PetPortrait_lixinwuzhe.png",source_id=3719,type_ids={20,19}},{avatar="PetAvatar_3760.png",description="体内积蓄着高压的热能，需要经历一次足够猛烈的高温才能进化。田野里偶尔传来的“砰”一声闷响，多半是哪只不走运的精灵踩到了它。村民们在收割季都互相提醒多看脚下，别踩鼓起来的苞米仔。",id="pet_000530",name="苞米仔",page_title="苞米仔",pictorial_book_id=425,portrait="PetPortrait_baomizai.png",source_id=3759,type_ids={3,4}},{avatar="PetAvatar_3761.png",description="田野里最吵的精灵，噼里啪啦的爆裂声是它们的开场白，能自行生成高温玉米粒，枪口永远冒着热气。它的信条是：先开枪，再打招呼。打完招呼，再开一枪。",id="pet_000531",name="炮米花",page_title="炮米花",pictorial_book_id=426,portrait="PetPortrait_baomihua.png",source_id=3760,type_ids={3,4}}},page_title="铅字幻梦",season_label="S3赛季",source_id=3,task_count=40,visual={backdrop="Season_3_HandbookBg.png",battle_pass_background="BattlePass_23003_Background.png",hero="Season_3_Hero.png",title="Season_3_Title.png"},window={["end"]="2026-09-10 03:59:59",start="2026-07-16 04:00:00",timezone="UTC+8"}},season_4={adventure_id=104,adventure_name="月涌狂想",battle_pass_id="battle_pass_23004",chapter_count=6,collection_tasks={{available_from="2026-09-30 04:00:00",conditions={"集齐S4赛季的赛季新精灵进化链"},name="S4图鉴：收集该赛季的所有新精灵进化链",reward_id="reward_201108"}},encounter_text="于月涌狂想赛季相遇",id="season_4",name="月涌狂想",new_pets={{avatar="PetAvatar_3236.png",description="传说它是远古时期坠入卡洛西亚大陆的陨石，被充满魔力的土地赋予了生命。在它身边能测到一片明显异常的引力场，随手扔出的石子也会不由自主地朝它靠拢，所幸大多个体性格温和，是学者们研究地外星体的重要来源。",id="pet_000597",name="星星眼",page_title="星星眼",pictorial_book_id=463,portrait="PetPortrait_QiuQiu1.png",source_id=3236,type_ids={20}},{avatar="PetAvatar_3542.png",description="皇家研究院的旧标本室里，有一只已经风干很久的虫。某天夜里，值班研究员听见木架上传来一声轻轻的\"嗒\"，回头看时，标本针孔里空空如也。从那以后，未完虫学会了绕开所有尖锐的东西走路，遇到危险就地一躺，装作标本。",id="pet_000598",name="未完虫",page_title="未完虫",pictorial_book_id=454,portrait="PetPortrait_WeiWanChong1.png",source_id=3542,type_ids={17,13}},{avatar="PetAvatar_3574.png",description="洛克走过湿地时，会让热团团带路。只有热团团走过的路面踩上去暖和，别的精灵也会沿着这条路暖身子，久而久之就形成了新的路线。热团团不知道这些，缩一团歇着呢。",id="pet_000599",name="热团团",page_title="热团团",pictorial_book_id=449,portrait="PetPortrait_ReTuanTuan1.png",source_id=3574,type_ids={4,13}},{avatar="PetAvatar_3575.png",description="牧民说只要焰米龙飞过的地方草就长得快，露水干得早，播种能提前半个月，沿线的牧民从小就知道，踩温热地面走夜路不冻脚。焰米龙不知道这些，它们心里只有自己的球。",id="pet_000600",name="焰米龙",page_title="焰米龙",pictorial_book_id=450,portrait="PetPortrait_ReTuanTuan2.png",source_id=3575,type_ids={4,13}},{avatar="PetAvatar_3576.png",description="传说最早的村镇都挨着圣凯布米龙每天路过的路线建起来，洛克们沿着它留下的温热痕迹耕种、修路。地图上的路，最初就是这么画下来的。如今大部分洛克都不记得这些路是从哪来的，只知道这条路一直比别处暖和。",id="pet_000601",name="圣凯布米龙",page_title="圣凯布米龙",pictorial_book_id=451,portrait="PetPortrait_ReTuanTuan3.png",source_id=3576,type_ids={4,13}},{avatar="PetAvatar_3589.png",description="玳龟自己也搞不懂头骨里的球体是什么，魔法学院图书馆里有本旧书写过一句话：这世界被一只很大的龟驮着，那只龟又被更大的龟驮着，一路往下，数不到头。玳龟不识字，它只是每天慢慢地驮着自己的小球晃悠。",id="pet_000602",name="玳龟",page_title="玳龟",pictorial_book_id=455,portrait="PetPortrait_DaiGui1.png",source_id=3589,type_ids={20}},{avatar="PetAvatar_3590.png",description="研究员检测玳塔胸腔中层层嵌套的幻系能量时，往内每深入一层，能量结构就更复杂，直到探测器承受不住而中断记录。而那本书记载乌龟塔理论的书从此被移出寓言分类，重新归档为待验证的世界模型。",id="pet_000603",name="玳塔",page_title="玳塔",pictorial_book_id=456,portrait="PetPortrait_DaiGui2.png",source_id=3590,type_ids={20}},{avatar="PetAvatar_3664.png",description="据说它们最早是地系研究院造出来测风用的，如今已经形成了自己的族群。它们的身体极轻，风一起头顶的杯子便\"咔哒咔哒\"地转起来，风一停又落回地面。",id="pet_000604",name="量风碗",page_title="量风碗",pictorial_book_id=457,portrait="PetPortrait_LiangFengWan1.png",source_id=3663,type_ids={15,19}},{avatar="PetAvatar_3663.png",description="测风蝉知道风要从哪边来，也知道风要停多久。研究院早就换上了新一代的电子测风仪，那些造它们的老工程师大多也已经退休了。它们每天照旧停在山口和楼顶，等待着风来，像是在等一个再也不会来的洛克下班。",id="pet_000605",name="测风蝉",page_title="测风蝉",pictorial_book_id=458,portrait="PetPortrait_LiangFengWan2.png",source_id=3664,type_ids={15,19}},{avatar="PetAvatar_3759.png",description="迷雾森林曾经的原住民，如今已在卡洛西亚大陆几乎绝迹。胸口嵌着一颗黄色宝石，据说封着一股来历不明的力量。它们沉默寡言，独自穿行于林间的雾气之中，遇到别的精灵便远远绕开，一整个白天都说不上一句话。",id="pet_000606",name="诅咒狼灵",page_title="诅咒狼灵",pictorial_book_id=443,portrait="PetPortrait_LangLing1.png",source_id=3761,type_ids={17,20}},{avatar="PetAvatar_3762.png",description="在有月亮的夜里，光芒会顺着它们胸前毛发的边缘缓缓流淌。它开始学会踏着月光潜行，落地几乎无声。仍是独来独往，很少与其他精灵哪怕是同族并肩行动，即便在同一片林子里遇见，也只是遥遥对望一眼便各自离开。",id="pet_000607",name="新月狼灵",page_title="新月狼灵",pictorial_book_id=444,portrait="PetPortrait_LangLing2.png",source_id=3762,type_ids={17,20}},{avatar="PetAvatar_3763.png",description="独自行走的离群之狼，月缺时它力量最弱，只是安静地趴在某块山石上休息。月圆那一夜，它会从月光最亮的地方走出来。当你看见银月狼王的时候，它已经看了你很久了，如果挥手打招呼的话，它也只是远远的点头致意。",id="pet_000608",name="银月狼王",page_title="银月狼王",pictorial_book_id=445,portrait="PetPortrait_LangLing3.png",source_id=3763,type_ids={17,20}},{avatar="PetAvatar_3764.png",description="月光下很难看到新月鹭，它们会融入月光在水面的倒影里，啄水里的月光。月亮躲进云里时，才发现岸边一直站着一只缩着脖子的新月鹭，好像刚才什么都没发生。",id="pet_000609",name="新月鹭",page_title="新月鹭",pictorial_book_id=446,portrait="PetPortrait_XinYueLu1.png",source_id=3764,type_ids={15,9}},{avatar="PetAvatar_3765.png",description="月辉鹭蹲在水面的月亮倒影上，一动不动，就像在孵月亮。有的洛克相信月亮发光不是因为月亮自己会发光，是因为有月辉鹭蹲着把光芒传输给月亮，也有洛克持相反态度。",id="pet_000610",name="月辉鹭",page_title="月辉鹭",pictorial_book_id=447,portrait="PetPortrait_XinYueLu2.png",source_id=3765,type_ids={15,9}},{avatar="PetAvatar_3766.png",description="月使鹭纳出没的地方，天上的月亮只剩一道细弧。月光全在它们身上，它们是这片湖区最亮的夜晚光源。等到它们换羽的日子，羽毛上的月光会跟着脱落，洒回天上，月亮又会重新变圆。",id="pet_000611",name="月使鹭纳",page_title="月使鹭纳",pictorial_book_id=448,portrait="PetPortrait_XinYueLu3.png",source_id=3766,type_ids={15,9}},{avatar="PetAvatar_3767.png",description="章脑丸思考的时候，半透明的身体里会有一小串光顺着神经一节一节亮过去，它们总是成群漂在近岸的浅水里，小脑袋一起明明灭灭，那是它们在聊天。",id="pet_000612",name="章脑丸",page_title="章脑丸",pictorial_book_id=452,portrait="PetPortrait_ZhangNaoWan1.png",source_id=3767,type_ids={6,5}},{avatar="PetAvatar_3768.png",description="极聪明的精灵，无数光点从四周向智辉章脑汇聚，又从它这里散回四周，族群里所有的所见所感，最终都汇入它的脑中。它们偏爱有洛克生活的水域，能理解洛克说话的语气。",id="pet_000613",name="智辉章脑",page_title="智辉章脑",pictorial_book_id=453,portrait="PetPortrait_ZhangNaoWan3.png",source_id=3768,type_ids={6,5}},{avatar="PetAvatar_3771.png",description="洛克大道上打翻的垃圾桶、面包店里少了一半的糕点、驻地里凭空消失的徽章，十有八九是这些小家伙干的。它们从不单独行动，三两成群蹲在街角盯梢，看见落单的精灵和洛克便一拥而上。",id="pet_000614",name="小浣蛋",page_title="小浣蛋",pictorial_book_id=459,portrait="PetPortrait_XiaoHuanDan1.png",source_id=3771,type_ids={18}},{avatar="PetAvatar_3772.png",description="每一群小浣蛋背后都跟着一只黑手浣熊，翻垃圾桶它先翻，新鲜的垃圾它先吃。黑手浣熊对体型更大的精灵大哥很有礼貌低头哈腰，尾巴摇得飞起，转头就打个手势让小浣蛋们偷偷去掏大哥的家底。",id="pet_000615",name="黑手浣熊",page_title="黑手浣熊",pictorial_book_id=460,portrait="PetPortrait_XiaoHuanDan2.png",source_id=3772,type_ids={18}},{avatar="PetAvatar_3773.png",description="洛克走过废弃的旧宅，忽然听到铃声在耳边响起，回头却什么也看不见，大多是幽铃藏在墙角恶作剧。它们并不真的想吓着谁，只是喜欢看洛克东张西望找不着的样子。",id="pet_000616",name="幽铃",page_title="幽铃",pictorial_book_id=461,portrait="PetPortrait_YouLing1.png",source_id=3773,type_ids={17}},{avatar="PetAvatar_3774.png",description="成长后恶作剧也升了级，它会招呼一群幽铃埋伏在旧宅子的各个角落，等洛克推门进来，就四处发出声音，把洛克吵得团团转，自己却都不露面。被吓的洛克若是不生气，它们便会觉得有点没意思，悻悻地散去。",id="pet_000617",name="摇铃魔偶",page_title="摇铃魔偶",pictorial_book_id=462,portrait="PetPortrait_YouLing3.png",source_id=3774,type_ids={17}},{avatar="PetAvatar_3775.png",description="布灵的样子是一只手工缝的小熊，真正的它其实是从熊头顶露出来的那一小团黄色能量，布偶只是它给自己找的一个不那么显眼的壳。据说它的家乡是一片被黑暗吃掉过的星空，所以它到现在都怕黑。",id="pet_000618",name="布灵",page_title="布灵",pictorial_book_id=464,portrait="PetPortrait_BuLing1.png",source_id=3775,type_ids={20,6}},{avatar="PetAvatar_3776.png",description="布灵布灵对太阳和月亮没什么感觉，它们家乡的星空曾经比这里的更亮更大，可惜后来都熄灭了。它们真正着迷的是洛造光源，天一黑，它们会从街角、屋檐下、井盖缝里一个个悄悄冒出来，围着灯柱看很久很久。",id="pet_000619",name="布灵布灵",page_title="布灵布灵",pictorial_book_id=465,portrait="PetPortrait_BuLing2.png",source_id=3776,type_ids={20,6}}},page_title="月涌狂想",season_label="S4赛季",source_id=4,task_count=30,visual={backdrop="Season_4_HandbookBg.png",battle_pass_background="BattlePass_23004_Background.png",hero="Season_4_Hero.png",title="Season_4_Title.png"},window={["end"]="2026-11-05 03:59:59",start="2026-09-10 04:00:00",timezone="UTC+8"}}}